fn consider_history(data){
if busy {return}
 let rows=try {data.messages} catch {nil}
 if rows==nil {return}
 let latest="" let fingerprint="" let recent=[]
 for row in rows {
  let lane=try {row.lane} catch {""}
  let role=try {row.role} catch {""}
  let speaker=try {row.speaker.kind} catch {"person"}
  if lane=="person" && role=="tool" && (try {row.tool_name=="ask_user_question"} catch {false}) {
   let answer=try {row.content.parse_json()} catch {nil}
   let answered=try {answer.kind=="user_question_answer" && answer.status=="answered" && answer.answers!=nil} catch {false}
   if answered {
    latest="用户回答上一项偏好问题："+answer.answers.to_json()
    let stamp=try {row.persisted_at} catch {""}
    fingerprint=""+stamp+"|"+latest
    recent.push({role:"user",text:latest})
    if recent.len()>6 {recent.remove(0)}
   }
  }
  if lane=="person" && (role=="user" || role=="assistant") {
   let text=try {row.display_text} catch {row.content}
   if text==nil {text=row.content}
   if role=="user" && speaker!="app" && text!=bridge_prompt && text.strip_prefix("[TrendyHear 偏好助手]")==text && text.strip_prefix("[from the app]")==text {
    latest=text
    let stamp=try {row.persisted_at} catch {""}
    fingerprint=""+stamp+"|"+text
   }
   if speaker!="app" && text!=bridge_prompt && text.strip_prefix("[TrendyHear 偏好助手]")==text && text.strip_prefix("[from the app]")==text {
    recent.push({role:role,text:short_text(text,1200)})
    if recent.len()>6 {recent.remove(0)}
   }
  }
 }
 if latest=="" || fingerprint==seen_reply {return}
 seen_reply=fingerprint
 extraction_epoch=extraction_epoch+1
 if pending_proposal!=nil {forget_proposal()}
 conversation_context=recent
 extract_preferences(latest,recent,extraction_epoch,fingerprint)
}
